public partial class Report_WinLostSummary1 : PageBase
{
    protected string ToDay = string.Format("{0:MM/dd/yyyy}", DateTime.Today);
    protected string MinDay = "";
    protected string MaxDay = "";
    protected string FDay = "";
    protected string TDay = "";
    string fileName = "";
    string key = "winlostsummary";
    private RMReportUtils utilsBARM = null;
    protected void Page_Load(object sender, EventArgs e)
    {
        utilsBARM = new RMReportUtils(RMReportUtils.ReportName.ReportWLSummary, RMReportUtils.RMType.BARM);

        if (Request["IsExport"] == "1")
        {
            fileName = "WinLostSummary-" + DateTime.Today.ToShortDateString().Replace("/", "-");
            //ExportToExcel(fileName);
            string rpt = CastAide.AsString(CacheService.CreateInstance(Sunplus.Core.CachingLib.CacheType.ShareCached).Get(key));

            if (string.IsNullOrEmpty(rpt))
            {
                rpt = getcontent();
            }

            Sunplus.Accounting.Business.Report.Reports.ExportToExcel(rpt, fileName);
        }
        else
            content.Text = getcontent();
    }
    string getcontent()
    {
        StringBuilder html = new StringBuilder();
        DateTime fdate = DateTime.Today, tdate = DateTime.Today;
        string norow = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("NoInformation.htm");
        try
        {
            TemplateHandler.Assign(ref norow, "{tdno}", "6");
            TemplateHandler.Assign(ref norow, "{bgcolor-nodata}", "bgcolor-nodata");
            if (!string.IsNullOrEmpty(Request["fdate"]) && !string.IsNullOrEmpty(Request["tdate"]) &&
                (!Validator.ValidDateMMDDYYYY(Request["fdate"], out fdate).IsSuccess() ||
                 !Validator.ValidDateMMDDYYYY(Request["tdate"], out tdate).IsSuccess()))
            {
                html.Append(Sunplus.Accounting.Core.Web.WebUtils.LoadHtml("WinLost/WLSummaryAllHeader.htm", new string[] { "{fdate}", "{tdate}" }, new string[] { fdate.ToShortDateString(), tdate.ToShortDateString() }));
                html.Append(Sunplus.Accounting.Core.Web.WebUtils.LoadHtml("WinLost/WLSummaryHeader.htm", new string[] { "{TypeName}" }, new string[] { "Bettype" }));
                TemplateHandler.Assign(ref norow, "{nodata}", (IbcError.DATE_INVALID_FORMAT_MSG));
                html.Append(norow);
                html.Append("<table>");
                return html.ToString();
            }

            fileName = "WLSummary-from-" + fdate.ToShortDateString() + "-to-" + tdate.ToShortDateString();

            string tplFromToDate = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("Report/CommonFilter.htm");
            ToDay = string.Format("{0:MM/dd/yyyy}", DateTime.Today);
            MinDay = string.Format("{0:MM/dd/yyyy}", DateTime.Today.AddMonths(-3));
            FDay = string.Format("{0:MM/dd/yyyy}", fdate);
            TDay = string.Format("{0:MM/dd/yyyy}", tdate);
            string fromDateCalendar = "<input type=\"text\" id=\"fdate\" readonly=\"readonly\" class=\"txtdate\" style=\"width: 100px; background-color: white;\" value=\"" + FDay + "\"/>";
            string toDateCalendar = "<input type=\"text\" id=\"tdate\" readonly=\"readonly\" class=\"txtdate\" style=\"width: 100px; background-color: white;\" value=\"" + TDay + "\"/>";
            TemplateHandler.Assign(ref tplFromToDate, "{fdate}", fromDateCalendar);
            TemplateHandler.Assign(ref tplFromToDate, "{tdate}", toDateCalendar);
            lblFromToDate.Text = tplFromToDate;

            //header
            html.Append(Sunplus.Accounting.Core.Web.WebUtils.LoadHtml("WinLost/WLSummaryAllHeader.htm", new string[] { "{msg}", "{col}" }, new string[] { "Summary report from " + fdate.ToShortDateString() + " to " + tdate.ToShortDateString(), "6" }));
            string WLheader = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummaryHeader.htm");
            TemplateHandler.Assign(ref WLheader, "{TypeName}", "Bettype");
            TemplateHandler.Assign(ref WLheader, "{width}", "10");

            DbResult rs = MatchWinLostReport.Acc_Rpt_WinLostSummary(fdate, tdate);
            DataTable dt = rs.ResultSet.Tables[0];

            #region declare variable
            string sp = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummarySportType.htm");
            string rows = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummaryAllRow.htm");
            string colspans = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummaryColspan.htm"), colspan = "";
            TemplateHandler.Assign(ref colspans, "{col}", "6");
            string totalrows = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummaryTotalRow.htm");
            TemplateHandler.Assign(ref totalrows, "{col}", "2");

            string odd_even = "";
            int index = 0, indexSport = 0;
            string pBetType = "", BetType = "", color = "", url = "";

            int SportType = 0;

            double BTypeWin = 0, BTypePos = 0, BTypeCom = 0, BTypeAd2 = 0;
            double SportWin = 0, SportPos = 0, SportCom = 0, SportAd2 = 0;
            double AllWin = 0, AllPos = 0, AllCom = 0, AllAd2 = 0;
            double IBCWin = 0, IBCPos = 0, IBCCom = 0, IBCAd2 = 0;
            double IBCSportWin = 0, IBCSportPos = 0, IBCSportCom = 0, IBCSportAd2 = 0;

            double Win = 0, Pos = 0, Com = 0, Ad2 = 0;
            double Detail = FormatHandler.GetDouble(rs.Outputs["_details"]);
            bool pLive = false, Live = false;
            string totalRowSportType = "";
            #endregion declare

            if (dt.Rows.Count > 0)
            {
                string sportname = "-";
                string bgcolorBettype = "evenrow";
                bool IsBettype = true;

                #region foreach
                foreach (DataRow dr in dt.Rows)
                {
                    BetType = dr["bType"].ToString();
                    Live = Convert.ToBoolean(dr["LiveIndicator"]);
                    SportType = FormatHandler.GetInt(dr["SportType"]);

                    // bettype or live
                    if ((BetType != pBetType) || (Live != pLive))
                    {
                        if (index > 1)
                        {
                            //color = "#dddddd";                            
                            color = " class='footernobold'";
                            string totalrow = totalrows.Clone().ToString();

                            TemplateHandler.Assign(ref totalrow, "{bgclass}", "class='bgnobold'");
                            Sunplus.Accounting.Business.Report.Reports.genrow(ref totalrow, color, "Total: ", BTypeWin, BTypePos, BTypeCom, BTypeAd2);
                            html.Append(totalrow);
                        }
                        BTypeWin = 0; BTypePos = 0; BTypeCom = 0; BTypeAd2 = 0;
                        pBetType = BetType;
                        pLive = Live;
                        index = 0;
                    }
                    index++;

                    #region //sport type
                    if (!sportname.Equals((CastAide.AsInt32(BetType) == 9) ? "Mix Parlay" : CacheRef.GetSportName(dr["SportType"]))
                        && !sportname.Equals((CastAide.AsInt32(BetType) == 29) ? Resources.Language.systemParlay : CacheRef.GetSportName(dr["SportType"])))
                    {
                        if (indexSport >= 1)
                        {
                            totalRowSportType = totalrows.Clone().ToString();
                            //color = "#99cccc";
                            color = "class='report-footer'";
                            Reports.genrow2(ref totalRowSportType, color, "<b>" + sportname + " Total:</b>", SportWin, SportPos, SportCom, SportAd2);
                            TemplateHandler.Assign(ref totalRowSportType, "{bgclass}", "class='footernobold'");
                            SportWin = SportPos = SportCom = SportAd2 = 0;

                            //reset value of old bettype
                            BTypeWin = 0; BTypePos = 0; BTypeCom = 0; BTypeAd2 = 0;

                            if (indexSport > 0) html.Append(totalRowSportType);

                            if ((IBCSportWin != 0) || (IBCSportPos != 0) || (IBCSportCom != 0) || (IBCSportAd2 != 0))
                            {
                                totalRowSportType = totalrows.Clone().ToString();
                                Sunplus.Accounting.Business.Report.Reports.genrow(ref totalRowSportType, color, "<b>IBC(8RM" + (utilsBARM.IsActive ? " + " + utilsBARM.DisplayName : string.Empty) + "):</b>", IBCSportWin, IBCSportPos, IBCSportCom, IBCSportAd2);
                                TemplateHandler.Assign(ref totalRowSportType, "{bgclass}", "class='footernobold'");
                                if (indexSport > 0) html.Append(totalRowSportType);
                                IBCSportWin = IBCSportPos = IBCSportCom = IBCSportAd2 = 0;                                
                            }

                            colspan = colspans.Clone().ToString();
                            TemplateHandler.Assign(ref colspan, "{msg}", "");
                            html.Append(colspan);
                        }

                        string sport = sp.Clone().ToString();

                        switch (CastAide.AsInt32(BetType))
                        {
                            case 9:
                                sportname = "Mix Parlay";
                                break;
                            case 29:
                                sportname = Resources.Language.systemParlay;
                                break;
                            default:
                                sportname = CacheRef.GetSportName(dr["SportType"]);
                                break;

                        }

                        TemplateHandler.Assign(ref sport, "{sporttype}", sportname);
                        if (Detail > 0)
                        {
                            switch (BetType)
                            {
                                case "9":
                                case "29":
                                    url = string.Empty;
                                    break;
                                default:
                                    url = "<a title='View' href='WinLostSummaryDetail.aspx?D=" + Detail + "&fdate=" + fdate.ToShortDateString() + "&tdate=" + tdate.ToShortDateString() + "&S=" + SportType + "&B=0&Live=0" + "' target='WinLostDetails'><div class='viewicon'></div></a>";
                                    break;
                            }

                            TemplateHandler.Assign(ref sport, "{url}", "<u>" + url + "</u>");
                        }
                        else
                        {
                            url = "&nbsp;&nbsp;&nbsp;";
                            TemplateHandler.Assign(ref sport, "{url}", url);
                        }
                        html.Append(sport);
                        string h = WLheader.Clone().ToString();
                        html.Append(h);
                        indexSport++;
                    }
                    #endregion

                    odd_even = (odd_even == "") ? "evenrow" : "";
                    string row = rows.Clone().ToString();
                    string btype = "";

                    Win = FormatHandler.GetDouble(dr["WinLost"]);
                    Pos = FormatHandler.GetDouble(dr["Position"]);
                    Com = FormatHandler.GetDouble(dr["Commission"]);
                    Ad2 = FormatHandler.GetDouble(dr["Admin2"]);
                    double l = Win + Pos + Com;

                    url = "";
                    if (index == 1 && Detail > 0)
                    {
                        string live = "0";
                        if (Live) live = "1";
                        //url = "<a href='WinLostSummaryDetail.aspx?D=" + Detail + "&fdate=" + fdate.ToShortDateString() + "&tdate=" + tdate.ToShortDateString() + "&S=" + SportType + "&B=" + BetType + "&Live=" + live + "' target='WinLostDetails'>D</a>";
                        switch (BetType)
                        {
                            case "9":
                            case "29":
                                url = string.Empty;
                                break;
                            default:
                                url = "<a title='View' href='WinLostSummaryDetail.aspx?D=" + Detail + "&fdate=" + fdate.ToShortDateString() + "&tdate=" + tdate.ToShortDateString() + "&S=" + SportType + "&B=" + BetType + "&Live=" + live + "' target='WinLostDetails'><div class='viewicon'></div></a>";
                                break;
                        }

                    }
                    if (Convert.ToString(dr["IBC"]).Equals("1"))
                    {
                        btype = "8RM";
                        IBCWin += Win; IBCSportWin += Win;
                        IBCPos += Pos; IBCSportPos += Pos;
                        IBCCom += Com; IBCSportCom += Com;
                        IBCAd2 += Ad2; IBCSportAd2 += Ad2;

                        IsBettype = false;
                    }
                    else if (Convert.ToString(dr["IBC"]).Equals("2") && utilsBARM.IsActive)
                    {
                        btype = utilsBARM.DisplayName;
                        IBCWin += Win; IBCSportWin += Win;
                        IBCPos += Pos; IBCSportPos += Pos;
                        IBCCom += Com; IBCSportCom += Com;
                        IBCAd2 += Ad2; IBCSportAd2 += Ad2;

                        IsBettype = false;
                    }
                    else
                    {
                        string strBetType = (CastAide.AsInt32(dr["bType"]) != 99) ? CacheRef.GetBettype(dr["bType"]) : "Others BetType";
                        if (Convert.ToBoolean(dr["liveindicator"])) btype += "<b><font color ='red'>Live! </font> " + strBetType + "</b>";
                        else btype += "<b>" + strBetType + "</b>";
                        if (BetType == "9" || BetType == "29") btype += "<b> (" + Convert.ToString(dr["Status"]) + " )</b>";

                        IsBettype = true;
                    }

                    TemplateHandler.Assign(ref row, "{odd_even}", (IsBettype ? bgcolorBettype : string.Empty));
                    Reports.genrow2(ref row, color, btype, Win, Pos, Com, Ad2);
                    TemplateHandler.Assign(ref row, "{link}", "<u>" + url + "</u>");
                    html.Append(row);

                    AllWin += Win; BTypeWin += Win; SportWin += Win;
                    AllPos += Pos; BTypePos += Pos; SportPos += Pos;
                    AllCom += Com; BTypeCom += Com; SportCom += Com;
                    AllAd2 += Ad2; BTypeAd2 += Ad2; SportAd2 += Ad2;
                }
                #endregion //end foreach

                #region //total
                totalRowSportType = totalrows.Clone().ToString();
                //color = "#99cccc";
                color = "class='report-footer'";
                Sunplus.Accounting.Business.Report.Reports.genrow(ref totalRowSportType, color, "<b>" + sportname + " Total:</b>", SportWin, SportPos, SportCom, SportAd2);
                TemplateHandler.Assign(ref totalRowSportType, "{bgclass}", "class='footernobold'");
                SportWin = SportPos = SportCom = SportAd2 = 0;

                if (indexSport > 0) html.Append(totalRowSportType);

                if ((IBCSportWin != 0) || (IBCSportPos != 0) || (IBCSportCom != 0) || (IBCSportAd2 != 0))
                {
                    totalRowSportType = totalrows.Clone().ToString();
                    TemplateHandler.Assign(ref totalRowSportType, "{bgclass}", "class='footernobold'");
                    Reports.genrow2(ref totalRowSportType, color, "<b>8RM:</b>", IBCSportWin, IBCSportPos, IBCSportCom, IBCSportAd2);
                    TemplateHandler.Assign(ref totalRowSportType, "{bgclass}", "class='footernobold'");
                    if (indexSport > 0)
                    {
                        html.Append(totalRowSportType);
                    }
                    IBCSportWin = IBCSportPos = IBCSportCom = IBCSportAd2 = 0;
                }

                colspan = colspans.Clone().ToString();
                TemplateHandler.Assign(ref colspan, "{msg}", "");
                html.Append(colspan);

                //All Total
                totalRowSportType = totalrows.Clone().ToString();


                double line = AllWin + AllPos + AllCom;
                Sunplus.Accounting.Business.Report.Reports.genrow(ref totalRowSportType, "", "<b>All Total:</b>", Reports.colorvalue(AllWin), Reports.colorvalue(AllPos), Reports.colorvalue(AllCom), "<b>" + Sunplus.Accounting.Business.Report.Reports.colorvalue(AllAd2) + "</b>", "<b>" + Sunplus.Accounting.Business.Report.Reports.colorvalue(line) + "</b>");
                TemplateHandler.Assign(ref totalRowSportType, "{colorline}", "style='background-color:#dddddd;'");
                html.Append(totalRowSportType);

                //Total IBC
                totalRowSportType = totalrows.Clone().ToString();
                //TemplateHandler.Assign(ref totalRowSportType, "{colorwin}", color);
                line = -IBCWin - IBCPos - IBCCom;
                Sunplus.Accounting.Business.Report.Reports.genrow(ref totalRowSportType, "", "<b>IBC(8RM" + (utilsBARM.IsActive ? " + " + utilsBARM.DisplayName : string.Empty) + ") Total:</b>",
                                                                  "<b>" +
                                                                  Sunplus.Accounting.Business.Report.Reports.colorvalue(
                                                                      -IBCWin) + "</b>", Reports.colorvalue(-IBCPos),
                                                                  Reports.colorvalue(-IBCCom),
                                                                  Reports.colorvalue(-IBCAd2), Reports.colorvalue(line));

                TemplateHandler.Assign(ref totalRowSportType, "{colorwin}", "style='background-color:#dddddd;'");
                html.Append(totalRowSportType);

                //colspan row
                colspan = colspans.Clone().ToString();
                TemplateHandler.Assign(ref colspan, "{msg}", "");
                html.Append(colspan);

                totalRowSportType = totalrows.Clone().ToString();
                double com = AllWin + AllPos + AllCom - AllAd2 - IBCWin;
                Sunplus.Accounting.Business.Report.Reports.genrow(ref totalRowSportType, "", "<b>GRAND TOTAL:</b>", "",
                                                                  "", "", "", Reports.colorvalue(com));
                html.Append(totalRowSportType);

                colspan = colspans.Clone().ToString();
                TemplateHandler.Assign(ref colspan, "{msg}", "Grand Total = (All:Line Total) - (IBC:WinLost) <br> IBC:Commission was ignored");
                html.Append(colspan);

                #endregion end total
            }
            else
            {
                #region no data
                string WL = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WLSummaryHeader.htm");
                TemplateHandler.Assign(ref WL, "{width}", "10");
                TemplateHandler.Assign(ref WL, "{TypeName}", "Bettype");
                html.Append(WL);
                TemplateHandler.Assign(ref norow, "{nodata}", (Resources.Language.thereisnodata));
                html.Append(norow);
                #endregion
            }
        }
        catch (Exception ex)
        {
            Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
            TemplateHandler.Assign(ref norow, "{nodata}", (ex.Message));
            html.Append("</table>");
            throw;
        }
        html.Append("</table>");

        #region footer
        string footer = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("WinLost/WinLostSummaryFooter.htm");
        TemplateHandler.Assign(ref footer, "{fdate}", fdate.ToShortDateString());
        TemplateHandler.Assign(ref footer, "{tdate}", tdate.ToShortDateString());
        TemplateHandler.Assign(ref footer, "{Today}", DateTime.Today.ToShortDateString());
        TemplateHandler.Assign(ref footer, "{Yesterday}", DateTime.Today.AddDays(-1).ToShortDateString());
        html.Append(footer);


        if (!string.IsNullOrEmpty(Request["F"]))
        {
            if (Session["roleId"] != null)
            {
                if (FormatHandler.GetInt(Session["roleId"]) == 10)
                {
                    DateTime date = Convert.ToDateTime(Request["date"]);

                    if (!string.IsNullOrEmpty(Request["date"]))
                    {
                        Sunplus.Accounting.DataAccess.IBCDLL.Accounting.MatchWinLostReport.Task_rptWinLost_UpdateTable(date);
                        string done = "<hr><b>Recal : Done (" + date.ToShortDateString() + ")<br>Time : " + date.ToShortDateString() + " " + DateTime.Now.ToLongTimeString() + "<b><hr>";
                        html.Append(done);
                    }
                }
                else
                {
                    html.Append("<hr><b>You don't have permission to recalculate the report right now!!!</b>");
                }
            }
        }
        #endregion end footer

        string tplTableBlank = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("TableBlank.htm");
        html.Append(tplTableBlank);



        long expired = CastAide.AsInt64(WebSettings.CacheExpire * 60 * 1000);
        CacheService.CreateInstance(Sunplus.Core.CachingLib.CacheType.ShareCached).Add(key, html.ToString(), expired);

        return html.ToString();
    }



